<?php

declare(strict_types=1);

namespace PetMatch\Presentation\Controllers;

use PetMatch\Infrastructure\Http\Request;
use PetMatch\Presentation\Responses\HtmlResponse;

final class PublicHomeController
{
    public function __invoke(Request $request): HtmlResponse
    {
        return HtmlResponse::ok(<<<'HTML'
<!DOCTYPE html>
<html lang="pt-BR">
<head>
<meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>PetMatch | Encontre seu próximo companheiro</title>
<style>
@import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;700&family=Fraunces:opsz,wght@9..144,600;9..144,700&display=swap');
:root{--ink:#20302c;--muted:#64736e;--paper:#f4f0e8;--surface:#fffdf8;--mint:#b9d8c7;--green:#27685b;--coral:#d76d4c;--line:rgba(32,48,44,.13)}*{box-sizing:border-box}body{margin:0;min-height:100vh;color:var(--ink);background:var(--paper);font-family:'DM Sans',sans-serif}.shell{width:min(1180px,calc(100% - 32px));margin:auto;padding:22px 0 56px}.nav{display:flex;justify-content:space-between;align-items:center;gap:18px;margin-bottom:56px}.brand{color:var(--green);font:700 28px 'Fraunces',serif}.nav-actions{display:flex;gap:10px}.button,button{border:0;border-radius:12px;padding:11px 16px;font:inherit;font-weight:700;cursor:pointer;text-decoration:none}.button-ghost{color:var(--green);background:transparent;border:1px solid var(--line)}.button-primary{color:#fffdf8;background:var(--green)}.button-coral{color:#fffdf8;background:var(--coral)}.hero{display:grid;grid-template-columns:minmax(0,1.1fr) minmax(260px,.9fr);gap:36px;align-items:end;margin-bottom:42px}.eyebrow{color:var(--coral);font-size:12px;font-weight:700;letter-spacing:.12em;text-transform:uppercase}h1{max-width:720px;margin:10px 0 16px;font:700 clamp(42px,7vw,82px)/.95 'Fraunces',serif;letter-spacing:-.055em}.hero p{max-width:560px;margin:0;color:var(--muted);font-size:18px;line-height:1.55}.hero-note{padding:24px;border:1px solid var(--line);border-radius:22px;background:var(--mint)}.hero-note strong{display:block;margin-bottom:8px;font:700 25px 'Fraunces',serif}.hero-note p{color:var(--ink);font-size:14px}.section-head{display:flex;justify-content:space-between;align-items:end;gap:16px;margin-bottom:18px}h2{margin:0;font:700 34px 'Fraunces',serif}.section-head p{margin:0;color:var(--muted)}.pet-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(250px,1fr));gap:18px}.pet-card{overflow:hidden;border:1px solid var(--line);border-radius:20px;background:var(--surface)}.pet-photo{width:100%;height:220px;object-fit:cover;display:block;background:var(--mint)}.placeholder{display:grid;place-items:center;color:var(--green);font:700 58px 'Fraunces',serif}.pet-content{padding:18px}.pet-content h3{margin:0 0 7px;font:700 27px 'Fraunces',serif}.pet-content p{min-height:44px;margin:0 0 16px;color:var(--muted);line-height:1.45}.pet-meta{display:flex;flex-wrap:wrap;gap:7px;margin-bottom:16px}.tag{padding:6px 9px;border-radius:999px;color:var(--green);background:#e8f1eb;font-size:12px}.pet-actions{display:grid;grid-template-columns:1fr 1fr;gap:8px}.pet-actions button{width:100%}.empty{padding:30px;border:1px dashed var(--line);border-radius:18px;color:var(--muted);background:rgba(255,253,248,.7)}.modal-backdrop{position:fixed;inset:0;display:grid;place-items:center;padding:18px;background:rgba(32,48,44,.48);z-index:5}.modal{width:min(440px,100%);padding:24px;border-radius:20px;background:var(--surface)}.modal-head{display:flex;justify-content:space-between;gap:12px;align-items:start}.modal h2{font-size:30px}.close{padding:4px 9px;color:var(--muted);background:transparent;font-size:22px}.tabs{display:grid;grid-template-columns:1fr 1fr;gap:6px;margin:22px 0 16px;padding:5px;border-radius:12px;background:#edf0e9}.tabs button{color:var(--muted);background:transparent}.tabs button.active{color:var(--green);background:var(--surface)}.stack{display:grid;gap:12px}label{display:grid;gap:6px;color:var(--muted);font-size:13px}input{width:100%;padding:12px 13px;border:1px solid var(--line);border-radius:10px;color:var(--ink);background:#fff;font:inherit}.error{min-height:20px;color:#a33f2a;font-size:13px}[hidden]{display:none!important}@media(max-width:760px){.hero{grid-template-columns:1fr}.nav{margin-bottom:34px}.nav-actions .button-ghost{display:none}.section-head{align-items:start;flex-direction:column}}
</style></head>
<body><div class="shell">
<nav class="nav"><div class="brand">PetMatch</div><div class="nav-actions"><a class="button button-ghost" href="/playground">Área da organização</a><button class="button button-ghost" id="likedButton" type="button" hidden>Meus interesses</button><button class="button button-ghost" id="requestsButton" type="button" hidden>Minhas solicitações</button><button class="button button-ghost" id="logoutButton" type="button" hidden>Sair</button><button class="button button-primary" id="authButton" type="button">Entrar</button></div></nav>
<header class="hero"><div><div class="eyebrow">Adoção com mais conexão</div><h1>O próximo encontro pode estar aqui.</h1><p>Conheça pets que estão esperando uma família. Explore livremente e crie sua conta quando encontrar um companheiro que chamou sua atenção.</p></div><aside class="hero-note"><strong>Olhe com calma.</strong><p>Para curtir, passar ou iniciar uma adoção, entre na sua conta. Assim guardamos suas escolhas e acompanhamos cada pedido.</p></aside></header>
<main><div class="section-head"><div><h2>Pets disponíveis</h2><p>Encontre uma história que combine com a sua.</p></div><button class="button button-ghost" id="refreshButton" type="button">Atualizar lista</button></div><div class="pet-grid" id="petGrid"><div class="empty">Carregando pets...</div></div><section id="likedSection" hidden><div class="section-head" style="margin-top:48px"><div><h2>Meus interesses</h2><p>Pets que você curtiu e pode conhecer melhor.</p></div></div><div class="pet-grid" id="likedGrid"></div></section><section id="favoritesSection" hidden><div class="section-head" style="margin-top:48px"><div><h2>Meus favoritos</h2><p>Pets que você salvou para revisitar.</p></div></div><div class="pet-grid" id="favoritesGrid"></div></section><section id="requestsSection" hidden><div class="section-head" style="margin-top:48px"><div><h2>Minhas solicitações</h2><p>Acompanhe o retorno das organizações.</p></div></div><div class="pet-grid" id="requestsGrid"></div></section><section id="verificationSection" hidden><div class="section-head" style="margin-top:48px"><div><h2>Minhas verificações</h2><p>As verificações de contato são necessárias para solicitar adoção.</p></div></div><div class="pet-grid" id="verificationGrid"></div></section></main></div>
<div class="modal-backdrop" id="authModal" hidden><section class="modal" role="dialog" aria-modal="true"><div class="modal-head"><div><div class="eyebrow">PetMatch</div><h2 id="authTitle">Entre para continuar</h2></div><button class="close" id="closeAuth" type="button" aria-label="Fechar">&times;</button></div><div class="tabs"><button id="loginTab" class="active" type="button">Entrar</button><button id="registerTab" type="button">Criar conta</button></div><form id="authForm" class="stack"><label id="nameField" hidden>Nome<input id="name" type="text" autocomplete="name"></label><label>E-mail<input id="email" type="email" autocomplete="email" required></label><label>Senha<input id="password" type="password" minlength="8" autocomplete="current-password" required></label><div class="error" id="authError"></div><button class="button button-primary" id="submitAuth" type="submit">Entrar</button></form></section></div><div class="modal-backdrop" id="adoptionModal" hidden><section class="modal" role="dialog" aria-modal="true"><div class="modal-head"><div><div class="eyebrow">Próximo passo</div><h2>Enviar solicitação</h2></div><button class="close" id="closeAdoption" type="button" aria-label="Fechar">&times;</button></div><p id="adoptionPetName"></p><form id="adoptionForm" class="stack"><label>Mensagem para a organização<textarea id="adoptionMessage" rows="5" placeholder="Conte um pouco sobre o lar que você quer oferecer."></textarea></label><div class="error" id="adoptionError"></div><button class="button button-coral" type="submit">Enviar solicitação</button></form></section></div>
<script>
const state={user:null,mode:'login',adoptionPetId:null},grid=document.getElementById('petGrid'),modal=document.getElementById('authModal'),errorBox=document.getElementById('authError');
function esc(value){return String(value).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;').replaceAll("'",'&#039;')}
async function api(path,options={}){const response=await fetch(path,{credentials:'same-origin',headers:{Accept:'application/json','Content-Type':'application/json',...(options.headers||{})},...options});const text=await response.text();const payload=text?JSON.parse(text):null;if(!response.ok)throw new Error(payload&&payload.error?payload.error:`HTTP ${response.status}`);return payload}
function openAuth(mode='login'){state.mode=mode;modal.hidden=false;document.getElementById('nameField').hidden=mode!=='register';document.getElementById('loginTab').classList.toggle('active',mode==='login');document.getElementById('registerTab').classList.toggle('active',mode==='register');document.getElementById('authTitle').textContent=mode==='login'?'Entre para continuar':'Crie sua conta';document.getElementById('submitAuth').textContent=mode==='login'?'Entrar':'Criar conta';errorBox.textContent=''}
function requireAuth(){if(state.user)return true;openAuth();return false}
async function swipe(petId,action){if(!requireAuth())return;try{await api(`/api/v1/pets/${petId}/swipe`,{method:'POST',body:JSON.stringify({action})});await loadPets()}catch(exception){if(exception.message==='Authentication required.')openAuth();else alert(exception.message)}}
async function favorite(petId){if(!requireAuth())return;try{await api(`/api/v1/pets/${petId}/favorite`,{method:'POST'});await loadFavorites()}catch(exception){alert(exception.message)}}
function renderPets(pets){if(!pets.length){grid.innerHTML='<div class="empty">Nenhum pet disponível no momento.</div>';return}grid.innerHTML=pets.map(pet=>{const photo=Array.isArray(pet.photos)&&pet.photos.length?`<img class="pet-photo" src="${esc(pet.photos[0].path)}" alt="Foto de ${esc(pet.name)}">`:`<div class="pet-photo placeholder">${esc(pet.name.slice(0,1))}</div>`;return `<article class="pet-card">${photo}<div class="pet-content"><h3>${esc(pet.name)}</h3><p>${esc(pet.description)}</p><div class="pet-meta"><span class="tag">${esc(pet.animal_type)}</span><span class="tag">${esc(pet.breed)}</span><span class="tag">${esc(pet.city)} / ${esc(pet.state)}</span></div><div class="pet-actions"><button class="button button-ghost" type="button" data-action="pass" data-pet="${pet.id}">Passar</button><button class="button button-coral" type="button" data-action="like" data-pet="${pet.id}">Curtir</button></div><button class="button button-ghost" type="button" data-favorite-pet="${pet.id}">Salvar nos favoritos</button></div></article>`}).join('');grid.querySelectorAll('[data-action]').forEach(button=>button.addEventListener('click',()=>swipe(button.dataset.pet,button.dataset.action)));grid.querySelectorAll('[data-favorite-pet]').forEach(button=>button.addEventListener('click',()=>favorite(button.dataset.favoritePet)))}
async function loadPets(){try{const result=await api('/api/v1/pets');renderPets(Array.isArray(result.data)?result.data:[])}catch(exception){grid.innerHTML=`<div class="empty">Não foi possível carregar os pets: ${esc(exception.message)}</div>`}}
function openAdoption(petId,name){if(!requireAuth())return;state.adoptionPetId=Number(petId);document.getElementById('adoptionPetName').textContent=`Você está enviando uma solicitação para ${name}.`;document.getElementById('adoptionError').textContent='';document.getElementById('adoptionModal').hidden=false}
async function loadLiked(){if(!state.user)return;try{const result=await api('/api/v1/me/liked-pets');const liked=Array.isArray(result.data)?result.data:[];document.getElementById('likedSection').hidden=false;document.getElementById('likedGrid').innerHTML=liked.length?liked.map(pet=>`<article class="pet-card"><div class="pet-content"><h3>${esc(pet.name)}</h3><p>${esc(pet.description)}</p><div class="pet-meta"><span class="tag">${esc(pet.animal_type)}</span><span class="tag">${esc(pet.breed)}</span><span class="tag">${esc(pet.city)} / ${esc(pet.state)}</span></div>${state.user.role==='adopter'?`<button class="button button-coral" type="button" data-adopt-pet="${pet.pet_id}" data-adopt-name="${esc(pet.name)}">Quero iniciar a adoção</button>`:'<span class="tag">Gestão disponível na área da organização</span>'}</div></article>`).join(''):'<div class="empty">Você ainda não curtiu nenhum pet disponível.</div>';document.querySelectorAll('[data-adopt-pet]').forEach(button=>button.addEventListener('click',()=>openAdoption(button.dataset.adoptPet,button.dataset.adoptName)))}catch(exception){document.getElementById('likedGrid').innerHTML=`<div class="empty">Não foi possível carregar seus interesses: ${esc(exception.message)}</div>`}}
async function loadFavorites(){if(!state.user)return;try{const result=await api('/api/v1/me/favorites');const favorites=Array.isArray(result.data)?result.data:[];document.getElementById('favoritesSection').hidden=false;document.getElementById('favoritesGrid').innerHTML=favorites.length?favorites.map(pet=>`<article class="pet-card"><div class="pet-content"><h3>${esc(pet.name)}</h3><p>${esc(pet.description)}</p><div class="pet-meta"><span class="tag">${esc(pet.animal_type)}</span><span class="tag">${esc(pet.breed)}</span></div><button class="button button-ghost" type="button" data-remove-favorite="${pet.pet_id}">Remover dos favoritos</button></div></article>`).join(''):'<div class="empty">Você ainda não salvou nenhum pet.</div>';document.querySelectorAll('[data-remove-favorite]').forEach(button=>button.addEventListener('click',async()=>{await api(`/api/v1/pets/${button.dataset.removeFavorite}/favorite`,{method:'DELETE'});await loadFavorites()}))}catch(exception){document.getElementById('favoritesGrid').innerHTML=`<div class="empty">Não foi possível carregar seus favoritos: ${esc(exception.message)}</div>`}}
async function withdrawRequest(requestId){if(!window.confirm('Cancelar esta solicitação de adoção?'))return;try{await api(`/api/v1/adoption-requests/${requestId}/withdraw`,{method:'PATCH'});await loadRequests()}catch(exception){alert(exception.message)}}
async function loadRequests(){if(!state.user)return;try{const result=await api('/api/v1/adoption-requests');const requests=Array.isArray(result.data)?result.data:[];document.getElementById('requestsSection').hidden=false;document.getElementById('requestsGrid').innerHTML=requests.length?requests.map(request=>`<article class="pet-card"><div class="pet-content"><h3>Pet #${request.pet_id}</h3><p>${request.message?esc(request.message):'Solicitação enviada sem mensagem.'}</p><span class="tag">${esc(request.status)}</span>${request.status==='pending'?`<br><button class="button button-ghost" type="button" data-withdraw-request="${request.id}">Cancelar solicitação</button>`:''}</div></article>`).join(''):'<div class="empty">Você ainda não enviou solicitações de adoção.</div>';document.querySelectorAll('[data-withdraw-request]').forEach(button=>button.addEventListener('click',()=>withdrawRequest(button.dataset.withdrawRequest)))}catch(exception){document.getElementById('requestsGrid').innerHTML=`<div class="empty">Não foi possível carregar suas solicitações: ${esc(exception.message)}</div>`}}
async function loadVerifications(){if(!state.user)return;try{const result=await api('/api/v1/auth/verifications');const verifications=Array.isArray(result.data)?result.data:[];const known=['email','whatsapp'].map(type=>verifications.find(item=>item.type===type)||{type,status:'pending'});document.getElementById('verificationSection').hidden=false;document.getElementById('verificationGrid').innerHTML=known.map(item=>`<article class="pet-card"><div class="pet-content"><h3>${item.type==='email'?'E-mail':'WhatsApp'}</h3><span class="tag">${esc(item.status)}</span></div></article>`).join('')}catch(exception){document.getElementById('verificationGrid').innerHTML=`<div class="empty">Não foi possível carregar suas verificações: ${esc(exception.message)}</div>`}}
async function loadSession(){try{state.user=(await api('/api/v1/auth/me')).data;document.getElementById('authButton').textContent=state.user.name;document.getElementById('likedButton').hidden=false;document.getElementById('requestsButton').hidden=false;document.getElementById('logoutButton').hidden=false;await loadLiked();await loadFavorites();await loadRequests();await loadVerifications()}catch(exception){state.user=null;document.getElementById('likedButton').hidden=true;document.getElementById('requestsButton').hidden=true;document.getElementById('logoutButton').hidden=true;document.getElementById('verificationSection').hidden=true}}
async function logout(){try{await api('/api/v1/auth/logout',{method:'POST',body:JSON.stringify({})});state.user=null;document.getElementById('authButton').textContent='Entrar';document.getElementById('likedButton').hidden=true;document.getElementById('requestsButton').hidden=true;document.getElementById('logoutButton').hidden=true;document.getElementById('likedSection').hidden=true;document.getElementById('favoritesSection').hidden=true;document.getElementById('requestsSection').hidden=true;document.getElementById('verificationSection').hidden=true}catch(exception){alert(exception.message)}}
document.getElementById('authButton').addEventListener('click',()=>state.user?null:openAuth());document.getElementById('logoutButton').addEventListener('click',logout);document.getElementById('likedButton').addEventListener('click',()=>document.getElementById('likedSection').scrollIntoView({behavior:'smooth'}));document.getElementById('requestsButton').addEventListener('click',()=>document.getElementById('requestsSection').scrollIntoView({behavior:'smooth'}));document.getElementById('closeAuth').addEventListener('click',()=>{modal.hidden=true});document.getElementById('closeAdoption').addEventListener('click',()=>{document.getElementById('adoptionModal').hidden=true});document.getElementById('loginTab').addEventListener('click',()=>openAuth('login'));document.getElementById('registerTab').addEventListener('click',()=>openAuth('register'));document.getElementById('refreshButton').addEventListener('click',loadPets);document.getElementById('authForm').addEventListener('submit',async event=>{event.preventDefault();errorBox.textContent='';const body={email:document.getElementById('email').value,password:document.getElementById('password').value};if(state.mode==='register')body.name=document.getElementById('name').value;try{const result=await api(state.mode==='login'?'/api/v1/auth/login':'/api/v1/auth/register',{method:'POST',body:JSON.stringify(body)});if(state.mode==='register'){openAuth('login');document.getElementById('email').value=body.email;errorBox.textContent='Conta criada. Entre para continuar.';return}state.user=result.data;modal.hidden=true;document.getElementById('authButton').textContent=state.user.name;document.getElementById('likedButton').hidden=false;document.getElementById('requestsButton').hidden=false;document.getElementById('logoutButton').hidden=false;await loadLiked();await loadRequests()}catch(exception){errorBox.textContent=exception.message}});document.getElementById('adoptionForm').addEventListener('submit',async event=>{event.preventDefault();const adoptionError=document.getElementById('adoptionError');adoptionError.textContent='';try{await api('/api/v1/adoption-requests',{method:'POST',body:JSON.stringify({pet_id:state.adoptionPetId,message:document.getElementById('adoptionMessage').value})});document.getElementById('adoptionModal').hidden=true;document.getElementById('adoptionMessage').value='';await loadRequests();alert('Solicitação enviada com sucesso.')}catch(exception){adoptionError.textContent=exception.message}});loadSession();loadPets();
</script></body></html>
HTML);
    }
}
